namespace {
void need(bool ok,const char* reason){if(!ok)throw std::runtime_error(reason);}
void set(SpaceInfinityProcessor& p,const juce::String& id,float v){auto* a=p.state.getParameter(id);need(a!=nullptr,"missing LFO parameter");a->setValueNotifyingHost(a->convertTo0to1(v));}
juce::Component* named(juce::Component& c,const juce::String& name){if(c.getName()==name)return &c;for(auto* child:c.getChildren())if(auto* found=named(*child,name))return found;return nullptr;}
juce::Slider* parameterSlider(juce::Component& c,const juce::String& id){if(c.getProperties()["modParam"].toString()==id)return dynamic_cast<juce::Slider*>(&c);for(auto* child:c.getChildren())if(auto* found=parameterSlider(*child,id))return found;return nullptr;}
juce::MouseEvent event(juce::Component& c,juce::Point<float> at){return {juce::Desktop::getInstance().getMainMouseSource(),at,{},1,0,0,0,0,&c,&c,juce::Time::getCurrentTime(),at,juce::Time::getCurrentTime(),1,false};}
double sound(float level){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","osc2Enabled"})set(*p,id,0);set(*p,"gain",.2f);set(*p,"subLevel",0);set(*p,"noiseLevel",0);set(*p,"osc1Gain",-30);set(*p,"routeA",0);set(*p,"ampSustain",1);set(*p,"attack",0);p->enableLfoCurve(1);set(*p,p->lfoParameterId(1,"CurveCount"),2);for(int i=0;i<2;++i){set(*p,p->lfoParameterId(1,"X")+juce::String(i),float(i));set(*p,p->lfoParameterId(1,"Y")+juce::String(i),level);}set(*p,p->lfoParameterId(1,"Enabled"),1);need(p->dropModulation("INFINITY:LFO:1","osc1Gain"),"LFO2 FX/synth route");set(*p,p->modulationDepthFor("INFINITY:LFO:1","osc1Gain"),.35f);p->prepareToPlay(48000,64);juce::AudioBuffer<float> b(2,64);double energy=0;for(int n=0;n<180;++n){juce::MidiBuffer midi;if(n==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);p->processBlock(b,midi);if(n>90)for(int i=0;i<64;++i){const float v=b.getSample(0,i);need(std::isfinite(v),"finite LFO audio");energy+=v*v;}}return energy;}
}
struct LfoTestPlayhead:juce::AudioPlayHead {double bpm=120;juce::Optional<PositionInfo> getPosition()const override {PositionInfo info;info.setTimeInSeconds(.25);info.setPpqPosition(.5);info.setBpm(bpm);info.setIsPlaying(true);return info;}};
int runDualLfoSmoke(){try {
    need(std::abs(timingui::cycleSeconds(true,1,2,120,false,false,0)-8)<1e-6,"four bars at 120 BPM");
    need(std::abs(timingui::cycleSeconds(true,1,2,150,false,false,0)-6.4)<1e-6,"time follows tempo");
    need(std::abs(timingui::cycleSeconds(true,1,2,120,true,false,0)-8/1.5)<1e-6,"triplet time");
    need(std::abs(timingui::cycleSeconds(true,1,2,120,false,true,0)-12)<1e-6,"dotted time");
    need(std::abs(timingui::cycleSeconds(true,1,2,120,false,false,2)-16)<1e-6,"ping pong full cycle");
    need(std::abs(timingui::cycleSeconds(false,.5,2,120,true,true,0)-2)<1e-6,"free Hz time independent of rhythm modifiers");
    need(std::abs(timingui::frequencyFromText("500 ms")-2)<1e-6&&std::abs(timingui::frequencyFromText("2 s")-.5)<1e-6,"duration entry converts to Hz");
    studio::EditableCurve c;c.count=2;c.x[1]=1;c.y[1]=1;studio::LfoTiming t;float memory=0;t.phase=.25f;need(std::abs(t.output(c,0,0,48000,memory)-.25f)<.00001,"phase offset");t.direction=1;need(std::abs(t.output(c,0,0,48000,memory)-.75f)<.00001,"reverse direction");t.phase=0;t.direction=2;need(std::abs(t.output(c,1.25,0,48000,memory)-.75f)<.00001,"ping pong direction");t.direction=0;t.delay=.5f;t.rise=1;need(t.output(c,1,.25,48000,memory)==0,"delay holds first graph value");need(std::abs(t.output(c,1,1,48000,memory)-.5f)<.00001,"rise fades graph influence");t.delay=t.rise=0;t.smooth=100;memory=0;need(t.output(c,1,1,48000,memory)<.001,"smoothing limits abrupt modulation");
    auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());
    for(auto size:{juce::Point<int>(800,760),{1000,790},{1180,820},{1500,950}}){editor->setSize(size.x,size.y);for(int lfo=0;lfo<2;++lfo){auto* pane=named(*editor,"LFO "+juce::String(lfo+1)+" editor");auto* graph=named(*editor,"LFO "+juce::String(lfo+1)+" curve");need(pane&&pane->isVisible()&&graph&&graph->isVisible(),"two LFO editors visible together");auto* time=dynamic_cast<juce::Label*>(named(*editor,"LFO "+juce::String(lfo+1)+" cycle time"));need(time&&time->isVisible()&&time->getWidth()>70&&time->getText().contains("s"),"visible cycle timing at every supported size");need(graph->getWidth()>70&&graph->getHeight()>25,"usable graph at every supported size");}}
    auto* pane=dynamic_cast<LfoPane*>(named(*editor,"LFO 1 editor"));need(pane!=nullptr,"timing pane");
    set(*p,p->lfoParameterId(0,"Sync"),1);set(*p,p->lfoParameterId(0,"Bars"),2);pane->select(0);
    auto* time=dynamic_cast<juce::Label*>(named(*editor,"LFO 1 cycle time"));need(time&&time->getText().contains("8.00 s"),"actual tempo timing label");
    LfoTestPlayhead uiHead;uiHead.bpm=150;p->setPlayHead(&uiHead);p->prepareToPlay(48000,128);juce::AudioBuffer<float> uiAudio(2,128);juce::MidiBuffer uiMidi;p->processBlock(uiAudio,uiMidi);pane->select(0);need(time->getText().contains("6.40 s"),"actual label follows host tempo");p->setPlayHead(nullptr);
    auto* rate=dynamic_cast<juce::Slider*>(named(*editor,"LFO 1 rate"));need(rate&&std::abs(rate->valueFromTextFunction("500 ms")-2)<1e-6,"attached rate retains duration parser");
    auto* delay=dynamic_cast<juce::Slider*>(named(*editor,"LFO 1 Delay"));auto* smooth=dynamic_cast<juce::Slider*>(named(*editor,"LFO 1 Smooth"));
    need(delay&&std::abs(delay->valueFromTextFunction("250 ms")-.25)<1e-6,"attached delay parses milliseconds");need(smooth&&std::abs(smooth->valueFromTextFunction("0.1 s")-100)<1e-6,"attached smooth parses seconds");
    for(auto id:{"chorusRate","flangerRate","phaserRate"}){auto* rateKnob=parameterSlider(*editor,id);need(rateKnob&&rateKnob->textFromValueFunction(.25).contains("0.250")&&std::abs(rateKnob->valueFromTextFunction("2 s")-.5)<1e-6,"FX rates show fractions and accept durations");}
    auto* echo=parameterSlider(*editor,"echoTimeL");auto* ir=parameterSlider(*editor,"irAttack");auto* tone=parameterSlider(*editor,"distTone");need(echo&&std::abs(echo->valueFromTextFunction("250 ms")-.25)<1e-6,"FX seconds field parses milliseconds");need(ir&&std::abs(ir->valueFromTextFunction("0.1 s")-100)<1e-6,"FX millisecond field parses seconds");need(tone&&tone->valueFromTextFunction("4 kHz")==4000,"FX frequency parses kHz");
    editor->setSize(1000,790);
    auto* hoverGraph=dynamic_cast<CurveEditor*>(named(*editor,"LFO 1 curve"));need(hoverGraph!=nullptr,"visible numbered graph");hoverGraph->mouseMove(event(*hoverGraph,hoverGraph->plotBounds().getCentre()));need(hoverGraph->getTooltip().contains("3.2s")&&hoverGraph->getTooltip().contains("50%"),"hover readout matches graph time and level");
    auto* secondPane=dynamic_cast<LfoPane*>(named(*editor,"LFO 2 editor"));need(secondPane!=nullptr,"second numbered pane");secondPane->select(1);
    auto* workbench=named(*editor,"Main envelopes, performance macros and LFO editor");need(workbench!=nullptr,"numbered envelope and LFO workbench");
    {const auto folder=juce::File::getCurrentWorkingDirectory().getChildFile("audition");folder.createDirectory();auto file=folder.getChildFile("Graph-Numbers-Detail.png");file.deleteFile();auto stream=file.createOutputStream();need(stream&&juce::PNGImageFormat{}.writeImageToStream(editor->createComponentSnapshot(editor->getLocalArea(workbench,workbench->getLocalBounds()),true,2),*stream),"native numbered graph close-up");}
    auto* graph=dynamic_cast<CurveEditor*>(named(*editor,"LFO 1 curve"));need(graph!=nullptr,"editable LFO graph");p->enableLfoCurve(0);set(*p,p->lfoParameterId(0,"CurveCount"),2);set(*p,p->lfoParameterId(0,"X")+"0",0);set(*p,p->lfoParameterId(0,"X")+"1",1);set(*p,p->lfoParameterId(0,"Y")+"0",0);set(*p,p->lfoParameterId(0,"Y")+"1",1);const auto other=p->lfoCurve(1);auto bounds=graph->plotBounds();auto at=juce::Point<float>(bounds.getCentreX(),bounds.getY()+bounds.getHeight()*.2f);graph->mouseDoubleClick(event(*graph,at));need(p->lfoCurve(0).count==3,"double click adds free LFO point");need(std::abs(p->lfoCurveValue(0,.5)-.8)<.0001,"curve evaluation uses added point");juce::MouseWheelDetails wheel;wheel.deltaY=.6f;auto bend=juce::Point<float>(bounds.getX()+bounds.getWidth()*.2f,bounds.getCentreY());graph->mouseWheelMove(event(*graph,bend),wheel);need(p->lfoCurve(0).bend[0]>.1f,"LFO segment bend");need(p->lfoCurve(1).y==other.y,"LFO1 editing leaves LFO2 unchanged");graph->mouseDoubleClick(event(*graph,at));need(p->lfoCurve(0).count==2,"double click removes LFO point");
    for(int shape=0;shape<6;++shape){graph->shape(shape);const int expected[]{5,3,2,2,4,2};need(p->lfoCurve(0).count==expected[shape],"simple LFO shapes use few anchors");for(int n=0;n<=100;++n){const float value=p->lfoCurveValue(0,n/100.0);need(std::isfinite(value)&&value>=0&&value<=1,"simple shape bounded");}if(shape==5)need(std::abs(p->lfoCurveValue(0,.25)-.5)<.0001,"two-anchor sidechain curve");}
    set(*p,p->lfoParameterId(0,"CurveEnabled"),0);for(int n=0;n<17;++n)set(*p,p->lfoPointId(0,n),1-std::abs(n/8.0f-1));need(p->lfoCurve(0).count==3,"collinear legacy anchors simplified");for(int n=0;n<=100;++n)need(std::abs(p->lfoCurveValue(0,n/100.0)-(1-std::abs(n/50.0-1)))<.00001,"legacy curve sound preserved");p->enableLfoCurve(0);need(p->lfoCurve(0).count==3,"editing keeps simplified anchors");
    for(auto field:{"Phase","Delay","Rise","Smooth","Direction","Mono","Triplet","Dotted","Host","Loopback"})need(p->state.getParameter(p->lfoParameterId(0,field))!=nullptr,"independent timing controls");
    set(*p,p->lfoParameterId(0,"Phase"),.37f);set(*p,p->lfoParameterId(1,"Smooth"),14);juce::MemoryBlock saved;p->getStateInformation(saved);auto recalled=std::make_unique<SpaceInfinityProcessor>();recalled->setStateInformation(saved.getData(),int(saved.getSize()));need(recalled->lfoCurve(0).bend==p->lfoCurve(0).bend,"free curve bends recall");need(std::abs(recalled->state.getRawParameterValue(p->lfoParameterId(0,"Phase"))->load()-.37f)<.0001,"phase recall");need(recalled->state.getRawParameterValue(p->lfoParameterId(1,"Smooth"))->load()==14,"independent smoothing recall");need(sound(1)>sound(0)*4,"LFO2 free curve modulates actual audio");
    auto anchored=std::make_unique<SpaceInfinityProcessor>();anchored->loadPreset(0);LfoTestPlayhead head;anchored->setPlayHead(&head);set(*anchored,anchored->lfoParameterId(0,"Host"),1);set(*anchored,anchored->lfoParameterId(0,"Sync"),0);set(*anchored,anchored->lfoParameterId(0,"Speed"),2);set(*anchored,anchored->lfoParameterId(0,"Mode"),0);need(anchored->dropModulation("INFINITY:LFO:1","irOutput"),"enable bounded rendering");anchored->prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);juce::MidiBuffer midi;anchored->processBlock(audio,midi);need(std::abs(anchored->lfoDisplayPhase(0)-(.5+256.0/48000*2))<.0001,"host anchoring accounts for every bounded chunk");anchored->setPlayHead(nullptr);
    std::cout<<"Dual LFO: visible independent graphs at four sizes, free points/bends, audio routing, phase/direction/delay/rise/smoothing and recall passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Dual LFO failure: "<<e.what()<<'\n';return 122;}}
